/*
 * Baked in at build time by vite.config.ts `define` (`uiCommit`), shown by shell/BuildVersion.tsx.
 */

/** The UI's source commit (full sha), or null when the build had none: no PAPERCLIP_UI_COMMIT and no git. */
declare const __UI_COMMIT__: string | null;
/** When the UI was built (the dev server: when it started), ISO. */
declare const __UI_BUILT_AT__: string;
